input.new_string:
.n-open { fill: var(--warn-bg); stroke: var(--warn); stroke-width: 1.3; stroke-dasharray: 5 3; }
.dev { fill: none; stroke: var(--muted); stroke-width: 1.2; stroke-dasharray: 6 4; }
.dep { fill: none; stroke: var(--fg); stroke-width: 1.2; stroke-dasharray: 5 4; }
.ball { fill: var(--surface); stroke: var(--fg); stroke-width: 1.3; }
.sock { fill: none; stroke: var(--fg); stroke-width: 1.3; }
.icon { fill: var(--surface); stroke: var(--fg); stroke-width: 1; }

.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); }
table { border-collapse: collapse; width: 100%; min-width: 860px; font-size: 13.5px; }
th, td { text-align: left; padding: 10px 14px; vertical-align: top; border-bottom: 1px solid var(--line); }
th { font-size: 11px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--muted); font-weight: 700; background: var(--zone); }
tr:last-child td { border-bottom: 0; }
td code { white-space: nowrap; }
td.group { font-size: 11px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--teal); font-weight: 700; background: var(--bg); }
.pill { display: inline-block; font-size: 11.5px; font-weight: 600; padding: 1px 8px; border-radius: 999px; border: 1px solid currentColor; white-space: nowrap; }
.pill.p { color: var(--teal); } .pill.open { color: var(--warn); } .pill.ok { color: var(--ok); }
@media (prefers-reduced-motion: no-preference)

